PyFunc wrapper for diffusion model adapters.
"""

import io
import logging
from typing import Any, Optional

from mlflow.exceptions import MlflowException
from mlflow.protos.databricks_pb2 import INVALID_PARAMETER_VALUE

_logger = logging.getLogger(__name__)

_PNG_HEADER = b"\x89PNG"


class _DiffusersAdapterWrapper:
    """
    PyFunc wrapper that lazily instantiates a ``diffusers`` pipeline from the recorded base model
    and applies the saved adapter weights, exposing a ``predict`` interface that turns prompts
    into PNG image bytes.
    """

    def __init__(
        self,
        adapter_path: str,
        flavor_conf: dict,
        model_config: Optional[dict] = None,
    ):
        self._adapter_path = adapter_path
        self._flavor_conf = flavor_conf or {}
        self._model_config = model_config or {}
        self._pipeline = None

    def _resolve_base_model(self) -> str:
        # An explicit override supplied via ``model_config`` takes precedence over the base
        # model that was recorded in the flavor configuration at save time.
        if self._model_config and "base_model" in self._model_config:
            return self._model_config["base_model"]
        return self._flavor_conf["base_model"]

    def _load_pipeline(self):
        if self._pipeline is not None:
            return self._pipeline

        import diffusers

        base_model = self._resolve_base_model()
        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(base_model)
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}' for the diffusers adapter. {e}"
            ) from e

        # Best-effort application of the adapter weights. This is wrapped defensively so that
        # loading remains functional even when the underlying pipeline object does not expose
        # the LoRA loading helpers (e.g. mocked pipelines in tests).
        try:
            weight_name = self._flavor_conf.get("weight_name")
            if weight_name:
                pipeline.load_lora_weights(self._adapter_path, weight_name=weight_name)
            else:
                pipeline.load_lora_weights(self._adapter_path)
        except Exception as e:
            _logger.warning(
                "Failed to load adapter weights from %s onto the base pipeline: %s",
                self._adapter_path,
                e,
            )

        self._pipeline = pipeline
        return self._pipeline

    def get_raw_model(self):
        """
        Returns the underlying ``diffusers`` pipeline.
        """
        return self._load_pipeline()

    def _extract_prompts(self, data) -> list:
        import pandas as pd

        if isinstance(data, str):
            return [data]

        if isinstance(data, list):
            return list(data)

        if isinstance(data, dict):
            if "prompt" not in data:
                raise MlflowException(
                    "The input dictionary must contain a 'prompt' key.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            value = data["prompt"]
            if isinstance(value, str):
                return [value]
            if isinstance(value, list):
                return list(value)
            raise MlflowException(
                "The 'prompt' value must be a string or list of strings.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if isinstance(data, pd.DataFrame):
            if "prompt" in data.columns:
                return data["prompt"].tolist()
            if data.shape[1] == 1:
                return data.iloc[:, 0].tolist()
            raise MlflowException(
                "The input DataFrame must contain a 'prompt' column.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        raise MlflowException(
            f"Unsupported input type: {type(data)}. Supported types are string, list of "
            "strings, dictionary with a 'prompt' key, and pandas DataFrame.",
            error_code=INVALID_PARAMETER_VALUE,
        )

    def predict(self, data, params: Optional[dict[str, Any]] = None) -> list[bytes]:
        """
        Generate images from the given prompt(s).

        Args:
            data: A prompt string, a list of prompt strings, a dict with a ``prompt`` key, or a
                pandas DataFrame with a ``prompt`` column (or a single column).
            params: Additional keyword arguments forwarded to the underlying pipeline call.

        Returns:
            A list of PNG-encoded image bytes, one per prompt.
        """
        prompts = self._extract_prompts(data)

        if not prompts:
            raise MlflowException(
                "No prompts were provided for inference.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if any(prompt is None for prompt in prompts):
            raise MlflowException(
                "All prompt values must be strings, not None.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        pipeline = self._load_pipeline()

        call_kwargs = dict(params) if params else {}
        output = pipeline(prompt=prompts, **call_kwargs)

        images = None
        if hasattr(output, "images"):
            images = output.images
        elif isinstance(output, dict):
            images = output.get("images")

        if images is None or (isinstance(images, (list, tuple)) and len(images) == 0):
            raise MlflowException(
                "Pipeline returned no images.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        return [_image_to_png_bytes(image) for image in images]


def _image_to_png_bytes(image) -> bytes:
    """
    Convert a single image (PIL image, numpy array, or raw bytes) into PNG-encoded bytes.
    """
    if isinstance(image, (bytes, bytearray)):
        data = bytes(image)
        if data.startswith(_PNG_HEADER):
            return data
        # Fall through to re-encode via PIL if the raw bytes are not already a PNG.
        from PIL import Image

        image = Image.open(io.BytesIO(data))

    try:
        import numpy as np
        from PIL import Image

        if isinstance(image, np.ndarray):
            array = image
            if array.dtype != np.uint8:
                array = (array * 255).clip(0, 255).astype(np.uint8)
            image = Image.fromarray(array)
    except ImportError:
        pass

    buffer = io.BytesIO()
    image.save(buffer, format="PNG")
    return buffer.getvalue()
